templates.literal:
`<div class="frow"><div class="kv"><span>${message.online ? presenceIndicators.online : presenceIndicators.offline} <b style="color:${message.name === myName2 ? '#ddd' : '#7af0a0'}">${escapeHtml2(message.name)}</b>${message.name === armada2.leader ? ' <span class="dim small">leader</span>' : ''}</span><span class="dim small">${escapeHtml2(message.hull)}${message.sys ? ` · ${message.sysId ? `<a href="#" data-cact="plot" data-sys="${escapeHtml2(message.sysId)}">${escapeHtml2(message.sys)}</a>` : escapeHtml2(message.sys)}` : ''}${message.landed ? ' · landed' : ''}</span></div>
      ${live ? `<div class="bars2"><div class="bar thin"><i style="width:${live.sh}%"></i></div><div class="bar thin"><i class="ar" style="width:${live.ar}%"></i></div></div>` : ''}
      ${message.name !== myName2 ? `<div class="frbtn"><button class="btn sm" data-cact="dm" data-n="${escapeHtml2(message.name)}">MESSAGE</button>${message.online && clientGameState.landed && clientGameState.landed!.site && clientGameState.landed!.site.own ? ` <button class="btn sm" data-cact="topen" data-n="${escapeHtml2(message.name)}">TRADE</button>` : ''}${lead ? ` <button class="btn sm" data-cact="alead" data-n="${escapeHtml2(message.name)}">MAKE LEADER</button> <button class="btn sm" data-cact="akick" data-n="${escapeHtml2(message.name)}">REMOVE</button>` : ''}</div>` : ''}</div>`

`<div class="dock${action ? ' on' : ''}"><div class="dhead"><span class="dletter">DOCK ${entryKey.letter}</span>${action ? '<span class="dact">ACTIVE</span>' : interactive && entryKey.lead ? `<button class="btn sm" data-act="dockgo" data-k="${index}">FLY WITH DOCK ${entryKey.letter}</button>` : ''}</div>
      <div class="drole">LEAD SHIP</div>${shipBox(clientGameState, entryKey.lead, 'No lead ship')}${shipPick(clientGameState, docksPayload, index, 'lead', entryKey.lead, interactive)}
      ${entryKey.wings
        .map(
          (
            dockShipPayload,
            innerIndex,
          ) => `<div class="drole">WINGMATE ${innerIndex + 1}</div>${shipBox(clientGameState, dockShipPayload, 'Empty wing slot')}${shipPick(clientGameState, docksPayload, index, innerIndex, dockShipPayload, interactive)}
        ${dockShipPayload ? `<div class="dcrews">${crewPick(clientGameState, index, innerIndex, 'cap', dockShipPayload.cap, interactive)}${crewPick(clientGameState, index, innerIndex, 'crew', dockShipPayload.crew, interactive)}</div>${dockShipPayload.repairT ? `<button class="btn sm" data-act="wingrep" data-uid="${dockShipPayload.uid}">RUSH REPAIRS ${credits(Math.round(repairBasis(clientGameState.A!, dockShipPayload.hull) * WING_REPAIR_COST))}</button>` : ''}` : ''}`,
        )
        .join('')}
    </div>`

`<div class="sect">WINGMATE REPAIRS</div><p class="dim small">Disabled wingmates repair automatically for free after ${WING_REPAIR_MIN} minutes. Pay the quoted fee to finish repairs now; the ship remains in your hangar until launch.</p>${
    disabled.length
      ? disabled
          .map((dockShipPayload) => {
            const cost = Math.round(
              repairBasis(clientGameState.A!, dockShipPayload.hull) * WING_REPAIR_COST,
            );
            return `<div class="kv"><span><b>${escapeHtml2(dockShipPayload.name)}</b> · ${escapeHtml2(clientGameState.A!.ships[dockShipPayload.hull].name)} <span class="dim small">· ${minutes(dockShipPayload.repairT)} min remaining</span></span><button class="btn sm" data-act="outfitterrep" data-uid="${escapeHtml2(dockShipPayload.uid)}"${playerPayload.credits < cost ? ' disabled title="Not enough credits"' : ''}>RUSH REPAIRS ${credits(cost)}</button></div>`;
          })
          .join('')
      : '<p class="dim small">No disabled wingmates awaiting repairs.</p>'
  }`

`<div class="kv"><span><b>${escapeHtml2(BUILDINGS[secondValue].name)}</b> <span class="dim small">${
            BUILDINGS[secondValue].produce
              ? Object.entries(BUILDINGS[secondValue].produce)
                  .map(
                    ([entryKey, value]) =>
                      `${entryKey === 'credits' ? credits(value * colonyLevelInfo.mult) + ' cr' : (value * colonyLevelInfo.mult).toFixed(1) + ' t ' + commodityName(entryKey)}/h`,
                  )
                  .join(', ')
              : buffText(BUILDINGS[secondValue].buff!)
          }</span></span><span><button class="btn sm" data-act="col" data-op="demolish" data-i="${index}">DEMOLISH</button></span></div>`

`<div class="igrid"><div>
    <div class="sect" style="margin-top:0">HOLDINGS</div>
    ${keyValueRow('<b>Net worth</b>', `<b class="cr">${credits2(worth)} cr</b>`)}${keyValueRow('Credits', credits2(playerPayload.credits))}${playerPayload.loan ? keyValueRow('Loan', `−${credits2(playerPayload.loan.bal)}`) : ''}
    ${keyValueRow('Ships', `${(playerPayload.shipless ? 0 : 1) + stored.length} <span class="dim small">(${credits2((playerPayload.shipless ? 0 : shipVal(playerPayload.ship)) + stored.reduce((firstValue, loadout) => firstValue + shipVal(loadout), 0))} cr)</span>`)}${docks}
    ${keyValueRow('Personal Station', site ? `Station Tier ${stationState.ops} · ${escapeHtml(systemsById[site.system].name)}` : '<span class="dim">none yet</span>')}
    ${keyValueRow('Colonies', (playerPayload.colonies || []).length ? playerPayload.colonies.map((component) => `${escapeHtml(component.name)} (Lv ${component.lv})`).join(', ') : '<span class="dim">none</span>')}
    ${keyValueRow(
      'Officers',
      (playerPayload.officers || []).length
        ? Object.entries(officers2)
            .sort((firstValue, secondValue) => Number(secondValue[0]) - Number(firstValue[0]))
            .map(
              ([radius, count]) =>
                `<span style="color:${RARITY[Number(radius)].color}">${count} ${RARITY[Number(radius)].name}</span>`,
            )
            .join(', ')
        : '<span class="dim">none</span>',
    )}
    ${keyValueRow('Material crates', crates)}${keyValueRow('Cargo', `${playerPayload.cargoUsed || 0} t <span class="dim small">(about ${credits2(cargoVal)} cr)</span>`)}
    ${join2 ? `<div class="sect">BLUEPRINTS</div>${join2}` : ''}
  </div><div>
    <div class="sect" style="margin-top:0">PROGRESS</div>
    ${keyValueRow('Main story', screenY.pass ? 'complete' : `chapter ${Math.min((screenY.step || 0) + 1, screenY.total || 1)} of ${screenY.total || '?'}`)}
    ${keyValueRow('Side stories', `${quantity.done.filter((positionX) => positionX.side).length} of 6`)}${keyValueRow('Contact stories', `${quantity.done.filter((positionX) => !positionX.side).length} finished · ${Object.values(quantity.contacts || {}).filter((component) => component.n >= 2).length} trusted contacts`)}
    ${keyValueRow('Faction stories', `${(playerPayload.arcs || []).filter((firstValue) => firstValue.done).length} of ${(playerPayload.arcs || []).length}`)}${keyValueRow('Farside expeditions', (playerPayload.expd && playerPayload.expd.n) || 0)}
    ${keyValueRow('Combat rating', `<b style="color:#ffd27a">${escapeHtml((playerPayload.rank || {}).name || 'Harmless')}</b>`)}${keyValueRow('Ships destroyed', credits2(state.kills || 0))}
    ${keyValueRow('Systems explored', `${(playerPayload.explored || []).length} of ${SYSTEMS.filter((starSystem) => !starSystem.arena).length}`)}${keyValueRow('Jumps made', credits2(state.jumps || 0))}
    ${keyValueRow('Credits earned', credits2(state.earned || 0))}${state.mined ? keyValueRow('Ore mined', `${credits2(state.mined)} t`) : ''}
    ${(quantity.active || []).length ? `<div class="sect">STORIES UNDER WAY</div>${quantity.active.map((firstValue) => `<div class="kv small"><span>${firstValue.side ? '★' : '✦'} ${escapeHtml(firstValue.name)}</span><span class="dim">step ${firstValue.step + 1} of ${firstValue.of}</span></div>`).join('')}` : ''}
  </div></div>`

`<div class="igrid"><div>
      <div class="sect" style="margin-top:0">SHIP</div>
      ${
        playerPayload.shipless
          ? '<p class="dim">No active ship.</p>'
          : `<div style="display:flex;gap:10px;align-items:center"><img src="${artworkUrl(shipHullAsset.img!)}" style="width:120px;height:90px;object-fit:contain"><div><b style="color:#fff;font-size:15px">${escapeHtml(shipHullAsset.name)}</b><div class="dim">"${escapeHtml(playerPayload.ship.name)}"</div></div></div>
      <div class="kv"><span>Shield / armor</span><span>${credits2(computedShipStats.shield)} / ${credits2(computedShipStats.armor)}</span></div><div class="kv"><span>Speed / turn</span><span>${credits2(computedShipStats.maxSpeed / 0.45)} / ${credits2((computedShipStats.turn * 57.3) / 3)}</span></div>
      <div class="kv"><span>Cargo</span><span>${playerPayload.cargoUsed} / ${computedShipStats.cargo} t</span></div><div class="kv"><span>Passenger seats</span><span>${(playerPayload.missions || []).filter((mission) => mission.type === 'passenger').reduce((sumValues, mission) => sumValues + (mission.pax || 0), 0)} / ${computedShipStats.passengerSeats} occupied</span></div><div class="kv"><span>Outfit space</span><span>${computedShipStats.free} of ${computedShipStats.space} free</span></div>
      <div class="kv"><span>Guns / turrets</span><span>${computedShipStats.guns}/${computedShipStats.maxGuns} · ${computedShipStats.turrets}/${computedShipStats.maxTurrets}</span></div><div class="kv"><span>Fuel</span><span>${Math.floor(((clientGameState.view && clientGameState.view.fuel) ?? playerPayload.fuel) / 100)} jumps</span></div>`
      }
      <div class="sect">COMBAT RATING</div><div class="kv"><span><b style="color:#ffd27a">${escapeHtml(rank.name)}</b></span><span class="dim">${credits2(rank.score)}${rank.next ? ` / ${credits2(rank.next)}` : ''}</span></div>
      <div class="rbar"><i style="width:${progressBar}%"></i></div><div class="dim small">Destroying ships raises your rating. Competent captains are offered Wanted contracts, and Dangerous ones get elite contracts.</div>
      <div class="sect">RECORD</div>${synBadge(playerPayload)}<div class="kv"><span>Commendations</span><span>${playerPayload.shards || 0}</span></div>
      <div class="kv"><span>Credit rating</span><span>${playerPayload.credit || 600}${playerPayload.loan ? ` · loan ${credits2(playerPayload.loan.bal)} cr` : ''}</span></div>
      <div class="kv"><span>Faction stories</span><span>${(playerPayload.arcs || []).filter((firstValue) => firstValue.done).length} of ${(playerPayload.arcs || []).length} complete</span></div>
      <div class="kv"><span>Farside expeditions</span><span>${(playerPayload.expd && playerPayload.expd.n) || 0} decoded</span></div>
    </div><div>
      <div class="sect" style="margin-top:0">CARGO</div>
      ${
        cargo.length
          ? cargo
              .map(([component, count]) => {
                const commodityDef = COMMODITIES.find(
                  (commodityDef) => commodityDef.id === component,
                );
                const bestSaleResult = bestSale(clientGameState, component);
                const grades = Object.entries(playerPayload.cargoLots?.byCommodity[component] || {})
                  .filter(([, quantity]) => quantity > 0)
                  .map(
                    ([game, quantity]) =>
                      `<div class="kv small"><span>↳ ${game}</span><span>${quantity} t ${inSpace ? `<button class="btn sm" data-jet="${component}" data-grade="${game}" data-n="${Math.min(5, quantity)}">DUMP ${Math.min(5, quantity)}</button> <button class="btn sm" data-jet="${component}" data-grade="${game}" data-n="${quantity}">DUMP ALL ${game.toUpperCase()}</button>` : ''}</span></div>`,
                  )
                  .join('');
                return `<div class="kv"><span>${escapeHtml(commodityDef ? commodityDef.name : component)}${bestSaleResult ? `<div class="small dim">Best nearby: <b style="color:var(--cr)">${credits2(bestSaleResult.price)}</b> at ${escapeHtml(bestSaleResult.p.name)}${bestSaleResult.jumps ? ` (${bestSaleResult.jumps} jump${bestSaleResult.jumps > 1 ? 's' : ''})` : ' (this system)'}${playerPayload.paid && playerPayload.paid[component] ? ` · you paid ${credits2(playerPayload.paid[component])}` : ''} ${bestSaleResult.jumps ? `<button class="btn sm" data-plot="${bestSaleResult.p.system}">PLOT</button>` : ''}</div>` : '<div class="small dim">No market you have visited nearby buys this.</div>'}</span><span>${count} t ${inSpace ? `<button class="btn sm" data-jet="${component}" data-n="${Math.min(5, count)}">DUMP 5</button> <button class="btn sm" data-jet="${component}" data-n="0">DUMP ALL</button>` : ''}</span></div>${grades}`;
              })
              .join('')
          : '<p class="dim">The hold is empty.</p>'
      }
      ${cargo.length ? `<div class="dim small">${inSpace ? 'Jettisoned cargo floats free. Raiders chasing you often go for it instead.' : 'You can jettison cargo in space.'}</div>` : ''}
      <div class="sect">MISSION CARGO</div>${
        (playerPayload.missions || [])
          .filter((mission) => mission.qty)
          .map(
            (mission) =>
              `<div class="kv"><span>${escapeHtml(mission.title)}</span><span>${mission.qty} t</span></div>`,
          )
          .join('') || '<p class="dim">None.</p>'
      }
    </div></div>`

`<div class="sect" style="margin-top:0">WINGMATE ORDERS</div><div class="dim small" style="margin-bottom:6px">Orders apply to your escorts, wingmates and fighters. Give the same order again to cancel it.</div>
      <div class="ords">${order2.map(([entryKey, count, entryKey2]) => `<button class="btn ${order3 === entryKey ? 'on' : ''}" data-ord="${entryKey}">${count} <span class="dim small">(${entryKey2})</span></button>`).join('')}</div>
      <div class="sect">WINGMATES${playerPayload.docks ? ` · DOCK ${playerPayload.docks.list[playerPayload.docks.active].letter}` : ''}</div>${(() => {
        const entryKey =
            playerPayload.docks && playerPayload.docks.list[playerPayload.docks.active],
          webSocket = entryKey ? entryKey.wings.filter(Boolean) : [];
        return webSocket.length
          ? webSocket
              .map((dockShipPayload) => {
                const shipHullAsset = clientGameState.A!.ships[dockShipPayload!.hull] || {};
                return `<div class="kv"><span><img src="${artworkUrl(shipHullAsset.img!)}" style="width:40px;height:28px;object-fit:contain;vertical-align:middle"> ${escapeHtml(dockShipPayload!.name)}</span><span class="dim">${dockShipPayload!.repairT ? 'under repair' : escapeHtml(shipHullAsset.name)}</span></div>`;
              })
              .join('')
          : '<p class="dim">No wingmates in your active dock. Assign stored ships as wingmates at your Personal Station (STATION, then DOCKS).</p>';
      })()}`

`<div data-mission-key="${escapeHtml(missionTarget.key)}" class="mcard${missionTarget.kind === 'story' || missionTarget.kind === 'arc' ? ' story' : missionTarget.kind === 'career' ? ' career' : ''}${missionTarget.urgent ? ' urgent' : ''}">
      ${missionTarget.kind === 'story' ? '<div class="storytag">MAIN STORY</div>' : missionTarget.kind === 'career' ? '<div class="careertag">CAREER</div>' : missionTarget.kind === 'arc' ? `<div class="storytag">${escapeHtml(missionTarget.tag || 'FACTION STORY')}</div>` : ''}
      <div class="t">${escapeHtml(missionTarget.title)}</div>
      <div class="mstat">${escapeHtml(missionTarget.status)}</div>${missionFactsHtml(clientGameState, missionTarget, true)}
      ${missionTarget.kind === 'story' && missionTargets2.some((missionTarget) => missionTarget.kind === 'career') ? `<details class="small dim"><summary>The story can wait until you know the ropes. Read more</summary>${escapeHtml(missionTarget.text)}</details>` : `<div class="dim small">${escapeHtml(missionTarget.text)}</div>`}
      <div class="mfoot"><button class="btn sm" data-pin="${escapeHtml(missionTarget.key)}" aria-pressed="${clientGameState.pinnedObjective === missionTarget.key}">${clientGameState.pinnedObjective === missionTarget.key ? 'UNPIN' : 'PIN'}</button><span class="dim small">${jumps}</span>${missionTarget.sys && missionTarget.sys !== clientGameState.sys ? `<button class="btn sm" data-plot="${escapeHtml(missionTarget.sys)}">PLOT COURSE</button>` : ''}${missionTarget.pendingQuest ? `<button class="btn sm mab" data-questdrop="${escapeHtml(missionTarget.pendingQuest)}" title="Abandon this story">✕</button>` : missionTarget.kind === 'job' || missionTarget.quest || (missionTarget.kind === 'arc' && missionTarget.tag === 'FARSIDE EXPEDITION') ? `<button class="btn sm mab" data-abandon="${escapeHtml(missionTarget.key)}" title="Drop this job">✕</button>` : ''}</div>
    </div>`

`<div class="sect">REFINERY${data.home ? ' · YOUR STATION' : ''}</div>
    <p class="dim">Turn raw cargo into trade goods. Choose what to make; the cost and result appear below. Construction crates use your station's separate workshop.</p>
    <div class="rrow refinery-form">
      <label>Make <select id="refrecipe">${RECIPES.map((recipe2) => `<option value="${recipe2.id}"${recipe2.id === draft.recipe ? ' selected' : ''}>${escapeHtml2(recipe2.name)}</option>`).join('')}</select></label>
      <label>Use grade <select id="refgrade"${recipe.pure || recipe.inputs[0] === 'plasma' ? ' disabled' : ''}>${['common', 'rich', 'pure'].map((game) => `<option${game === choice2.grade ? ' selected' : ''}>${game}</option>`).join('')}</select></label>
      <label>${recipe.inputs.length > 1 ? 'Tonnes of each material' : 'Tonnes'} <input id="refquantity" type="number" required min="${recipe.pure ? 3 : 1}" max="${Math.floor((choice2.mode === 'instant' ? refineryRules.instantCap : refineryRules.storedCap) / recipe.inputs.length)}" step="${recipe.pure ? 3 : 1}" value="${escapeHtml2(draft.n)}" inputmode="numeric"></label>
      <label>Speed <select id="refmode"><option value="stored"${choice2.mode === 'stored' ? ' selected' : ''}>Standard · ready later</option><option value="instant"${choice2.mode === 'instant' ? ' selected' : ''}>Express · ready now</option></select></label>
    </div>
    <div class="mcard" id="refquote" aria-live="polite">
      <b>YOU USE</b><p>${inputs}</p>
      ${recipe.pure ? '<p class="dim small">Composite Plating needs equal amounts of pure ore, gas and shards, in groups of 3 tonnes each.</p>' : ''}
      ${premium ? '<p class="jwarn">Rich and pure cargo sell for more, but give no extra output here. Common cargo is usually the better choice.</p>' : ''}
      ${reserved ? '<p class="jwarn">This uses cargo you still need for a delivery. You may refine it, but you will need to replace it to finish that job.</p>' : ''}
      ${!valid(choice2) ? '<p class="jwarn">Choose a whole amount within the limits above.</p>' : !enough ? '<p class="jwarn">Not enough of the selected cargo grade aboard. <button class="btn sm" data-act="ltab" data-t="trade">CHECK TRADE CARGO</button></p>' : ''}
      ${refineryQuote2 ? `<b>YOU GET</b><p>${(refineryQuote2.units / refineryRules.units).toFixed(3)} t ${escapeHtml2(title(refineryQuote2.output))} · ${refineryQuote2.mode === 'instant' ? 'ready to collect now' : `ready in about ${Math.ceil((refineryQuote2.duration + refineryRules.queueMs) / 60000)} min`}</p><p><b>Total cost: ${refineryQuote2.fee.toLocaleString()} credits</b>${refineryClientState.you!.credits < refineryQuote2.fee ? ' · not enough credits' : ''}</p><p class="dim small">${refineryQuote2.recovery}% of the usable material is recovered. Collect whole tonnes here; smaller amounts stay safely stored.${refineryQuote2.mode === 'stored' ? ` You can cancel during the first 30 seconds for ${refineryQuote2.cancelFee} credits.` : ''}</p>` : `<p class="dim">${refineryClientState.refineryCostError ? 'Could not load the current cost. Try again when connected.' : 'Checking the current cost…'}</p>`}
      ${refineryClientState.paused ? '<p class="jwarn">Solo is paused. Resume before starting a job.</p>' : ''}
      <button class="btn" data-refinery="submit"${refineryQuote2 ? ` data-id="${escapeHtml2(refineryQuote2.id)}"` : ''}${ready ? '' : ' disabled'}>${refineryClientState.refineryBusy ? 'STARTING…' : refineryQuote2 ? `START REFINING · ${refineryQuote2.fee.toLocaleString()} CR` : 'START REFINING'}</button>
      ${refineryClientState.refineryCostError ? '<button class="btn sm" data-refinery="retry">UPDATE COST</button>' : ''}
    </div>
    <div class="sect">DELIVERIES WANTED</div>${data.offers.map((miningOrder) => `<div class="rrow"><span>${miningOrder.qty} t ${escapeHtml2(miningOrder.grade)} ${escapeHtml2(title(miningOrder.cid))} · pays ${miningOrder.reward.toLocaleString()} credits</span><button class="btn sm" data-refinery="accept" data-order="1" data-id="${escapeHtml2(miningOrder.id)}" data-port="${escapeHtml2(miningOrder.port)}">ACCEPT DELIVERY</button></div>`).join('') || '<p class="dim">No deliveries wanted here right now.</p>'}${jobs}`

`<div class="lslot">${
      component
        ? `<b>${escapeHtml(component.name)}</b><div class="dim small">${escapeHtml(component.desc)}</div><button class="btn sm" data-act="lower" data-op="dismiss" data-i="${index}">DISMISS</button>`
        : `<div class="dim small">Empty berth</div>${
            docked
              ? `<select data-lowersel="${index}">${Object.entries(LOWER_DECK)
                  .filter(([entryKey]) => !length.includes(entryKey))
                  .map(
                    ([entryKey, lowerDeckRole]) =>
                      `<option value="${entryKey}">${escapeHtml(lowerDeckRole.name)} · ${escapeHtml(lowerDeckRole.desc)} · ${credits2(lowerDeckRole.cost)} cr</option>`,
                  )
                  .join(
                    '',
                  )}</select><button class="btn sm" data-act="lower" data-op="hire" data-i="${index}">HIRE</button>`
              : '<div class="dim small">Hire crew when docked.</div>'
          }`
    }</div>`

`<div class="dim small">Empty berth</div>${
            docked
              ? `<select data-lowersel="${index}">${Object.entries(LOWER_DECK)
                  .filter(([entryKey]) => !length.includes(entryKey))
                  .map(
                    ([entryKey, lowerDeckRole]) =>
                      `<option value="${entryKey}">${escapeHtml(lowerDeckRole.name)} · ${escapeHtml(lowerDeckRole.desc)} · ${credits2(lowerDeckRole.cost)} cr</option>`,
                  )
                  .join(
                    '',
                  )}</select><button class="btn sm" data-act="lower" data-op="hire" data-i="${index}">HIRE</button>`
              : '<div class="dim small">Hire crew when docked.</div>'
          }`

`<br><span>${escapeHtml2(commodityDef!.name)}: ${rawStellarBodys
            .map((rawStellarBody) => {
              const price2 = price(rawStellarBody, captainId);
              return price2 === null
                ? ''
                : `${escapeHtml2(rawStellarBody.name)} <b class="${price2 < commodityDef!.base * 0.92 ? 'lo' : price2 > commodityDef!.base * 1.08 ? 'hi' : ''}">${price2.toLocaleString()}</b>`;
            })
            .filter(Boolean)
            .join(' · ')} <span class="dim">(average ${commodityDef!.base})</span></span>`

`<br><span>${
        starSystem.stellars
          .filter((rawStellarBody) => rawStellarBody.svc && /[YO]/.test(rawStellarBody.svc))
          .map(
            (rawStellarBody) =>
              `${escapeHtml2(rawStellarBody.name)}: ${[rawStellarBody.svc!.includes('Y') ? 'shipyard' : '', rawStellarBody.svc!.includes('O') ? 'outfitter' : ''].filter(Boolean).join(' + ')}`,
          )
          .join(' · ') || '<span class="dim">No shipyard or outfitter.</span>'
      }</span>`

`${myHome ? '<span style="color:#ffd27a">◎ YOUR STATION · </span>' : ''}<b style="color:${FACTIONS[starSystem.faction].color}">${escapeHtml2(starSystem.name)}</b> · ${FACTIONS[starSystem.faction].name}${stateOfSys(starSystem.id) ? ' · ' + stateLine(starSystem.id) : ''} · danger <span class="dgr">${Array.from({ length: 7 }, (unused, index) => `<i class="${index < starSystem.danger ? 'on' : ''}"></i>`).join('')}</span> ${starSystem.danger}${lawfulness}${jumps}${seen ? '' : ' · <i>not yet visited</i>'}${extra}<br><span class="dim">${starSystem.stellars.map((rawStellarBody) => (rawStellarBody.site ? `${rawStellarBody.name}${clientGameState.sites && clientGameState.sites[rawStellarBody.id] ? ' (' + escapeHtml2(clientGameState.sites[rawStellarBody.id].owner) + ', Station Tier ' + clientGameState.sites[rawStellarBody.id].ops + ')' : ' (unclaimed)'}` : `${rawStellarBody.name} (${[rawStellarBody.svc!.includes('Y') && 'shipyard', rawStellarBody.svc!.includes('O') && 'outfitter', rawStellarBody.svc!.includes('T') && 'market', rawStellarBody.svc!.includes('B') && 'jobs'].filter(Boolean).join(', ') || 'no services'})`)).join(' · ') || 'No inhabited worlds.'}${fields ? ' · Mining: ' + fields : ''}${(() => {
        const cargo2 = Object.keys(
            (clientGameState.you && clientGameState.you!.cargo) || {},
          ).filter((component) => clientGameState.you!.cargo[component] > 0),
          buys = cargo2.filter((component) =>
            starSystem.stellars.some((rawStellarBody) => {
              const stellarBody = STELLARS[rawStellarBody.id];
              return (
                stellarBody &&
